-- ============================================================
-- OrionSales ERP (PostgreSQL dump)
-- Sistema gestione ordini e vendite
-- Convenzione: snake_case, date ISO
-- ============================================================

DROP SCHEMA IF EXISTS orion_sales CASCADE;
CREATE SCHEMA orion_sales;
SET search_path TO orion_sales;

CREATE TABLE sales_order_header (
  order_id              INTEGER PRIMARY KEY,
  order_number          VARCHAR(25),
  order_date            DATE,
  ship_date             DATE,
  due_date              DATE,
  status_code           INTEGER,
  customer_ref          INTEGER,            -- ⚠ riferimento al CRM!
  salesperson_ref       INTEGER,            -- ⚠ riferimento HR (BusinessEntityID)
  territory_ref         INTEGER,
  subtotal_amount       NUMERIC(19,4),
  tax_amount            NUMERIC(19,4),
  freight_amount        NUMERIC(19,4),
  total_due             NUMERIC(19,4),
  currency_iso          CHAR(3) DEFAULT 'USD'
);


CREATE TABLE sales_order_line (
  order_id        INTEGER,
  line_id         INTEGER,
  product_ref     INTEGER,    -- ⚠ riferimento al PIM
  qty             SMALLINT,
  unit_price      NUMERIC(19,4),
  unit_discount   NUMERIC(19,4),
  line_total      NUMERIC(19,4),
  offer_ref       INTEGER,
  PRIMARY KEY (order_id, line_id)
);


CREATE TABLE salesperson (
  salesperson_id   INTEGER PRIMARY KEY,  -- = BusinessEntityID HR
  territory_ref    INTEGER,
  sales_quota      NUMERIC(19,4),
  bonus            NUMERIC(19,4),
  commission_pct   NUMERIC(10,4),
  sales_ytd        NUMERIC(19,4),
  sales_last_year  NUMERIC(19,4)
);


CREATE TABLE territory (
  territory_id    INTEGER PRIMARY KEY,
  territory_name  VARCHAR(50),
  country_code    CHAR(3),
  region_group    VARCHAR(50),
  sales_ytd       NUMERIC(19,4),
  cost_ytd        NUMERIC(19,4)
);


CREATE TABLE offer (
  offer_id        INTEGER PRIMARY KEY,
  description     VARCHAR(255),
  discount_pct    NUMERIC(10,4),
  offer_type      VARCHAR(50),
  category        VARCHAR(50),
  start_date      DATE,
  end_date        DATE,
  min_qty         INTEGER,
  max_qty         INTEGER
);

